/**
 * Every error code this server documents. An error may still carry a code that is not
 * listed: the catalogue is open.
 */
export type ErrorCode = (typeof ErrorCodes)[keyof typeof ErrorCodes]

/**
 * The documented error codes per HTTP status. `never` marks a status whose error document
 * documents no specific code.
 */
export interface ErrorCodeByStatus {
  400:
    | "ATOMIC_OPERATIONS_INVALID"
    | "ATTRIBUTE_MEMBER_UNRECOGNIZED"
    | "CURSOR_MALFORMED"
    | "CURSOR_STALE"
    | "DATA_MEMBER_MISSING"
    | "FIELDSET_MEMBER_UNRECOGNIZED"
    | "FILTERING_UNRECOGNIZED"
    | "FILTER_VALUE_INVALID"
    | "INCLUSION_DEPTH_EXCEEDED"
    | "INCLUSION_NOT_ALLOWED"
    | "INCLUSION_UNRECOGNIZED"
    | "INCLUSION_UNSUPPORTED"
    | "LOCAL_ID_CONFLICT"
    | "LOCAL_ID_NOT_FOUND"
    | "LOCAL_ID_NOT_SUPPORTED"
    | "PAGINATION_KIND_UNKNOWN"
    | "QUERY_PARAM_MALFORMED"
    | "QUERY_PARAM_UNRECOGNIZED"
    | "RELATIONSHIP_COUNT_NOT_ALLOWED"
    | "RELATIONSHIP_TYPE_INAPPROPRIATE"
    | "REQUEST_BODY_INVALID_JSON"
    | "REQUEST_BODY_INVALID_JSON_API"
    | "REQUIRED_TOP_LEVEL_MEMBERS_MISSING"
    | "RESOURCE_IDENTIFIER_ID_INVALID"
    | "RESOURCE_IDENTIFIER_ID_MISSING"
    | "RESOURCE_IDENTIFIER_LID_INVALID"
    | "RESOURCE_IDENTIFIER_TYPE_INVALID"
    | "RESOURCE_IDENTIFIER_TYPE_MISSING"
    | "RESOURCE_ID_INVALID"
    | "RESOURCE_ID_MISSING"
    | "RESOURCE_TYPE_MISSING"
    | "SORTING_UNRECOGNIZED"
    | "SORTING_UNSUPPORTED"
    | "TOP_LEVEL_MEMBERS_INCOMPATIBLE"
    | "TOP_LEVEL_MEMBER_NOT_ALLOWED"
  401: "AUTHENTICATION_REQUIRED"
  403:
    | "ACCESS_DENIED"
    | "ADDITION_PROHIBITED"
    | "CLIENT_GENERATED_ID_NOT_SUPPORTED"
    | "CLIENT_GENERATED_ID_REQUIRED"
    | "FULL_REPLACEMENT_PROHIBITED"
    | "INSUFFICIENT_SCOPE"
    | "REMOVAL_PROHIBITED"
  404: "RELATIONSHIP_NOT_EXISTS" | "RESOURCE_NOT_FOUND"
  406: "MEDIA_TYPE_UNACCEPTABLE"
  409:
    | "ARTICLE_LOCKED"
    | "CLIENT_GENERATED_ID_ALREADY_EXISTS"
    | "RESOURCE_ID_CONFLICT"
    | "RESOURCE_TYPE_UNACCEPTABLE"
  415: "MEDIA_TYPE_UNSUPPORTED"
  422: "ATTRIBUTE_VALUE_INVALID" | "RELATED_ATTRIBUTE_OWNER_MISSING" | "RESOURCE_ID_UNDECODABLE"
  500:
    | "APPLICATION_ERROR"
    | "NO_RESOURCE_REGISTERED"
    | "RESPONSE_BODY_INVALID_JSON"
    | "RESPONSE_BODY_INVALID_JSON_API"
}

/**
 * The error codes only some operations raise, by operation id: what each adds to the codes its
 * status documents for every operation.
 */
export interface ErrorCodeByOperation {
  "delete.articles": "ARTICLE_LOCKED"
  "update.articles": "ARTICLE_LOCKED"
}

/**
 * The `meta` each documented code declares, by code. A code not listed carries untyped `meta`,
 * and one whose `meta` is optional may arrive without it.
 */
export interface ErrorMetaByCode {
  INSUFFICIENT_SCOPE: { requiredScopes: [string, ...string[]]; missingScopes: [string, ...string[]]; include?: string }
  REQUEST_BODY_INVALID_JSON: { original?: string } | undefined
  RESPONSE_BODY_INVALID_JSON: { original?: string } | undefined
}

/**
 * True when `err` is a `JsonApiError` and any of its error objects carries `code`. Only takes a
 * documented code; match an undocumented one with `hasErrorCode` from
 * '@haddowg/json-api-client'.
 */
export const hasErrorCode = hasErrorCodeRuntime as ErrorCodeGuard<ErrorCode>

/**
 * The first error object in `err` carrying `code`, with its `meta` typed when the code declares
 * one, or `undefined`. Only takes a documented code; find an undocumented one with `findError`
 * from '@haddowg/json-api-client'.
 */
export const findError = findErrorRuntime as ErrorFinder<ErrorCode, ErrorMetaByCode>

/**
 * Descriptor-bound client factory; wraps the generic runtime with this API’s `resourceMap`.
 * The server-level `atomic` capability is threaded in by default so `client.atomic` is wired
 * (a caller may still override it via `options.atomic`). The client type carries `ErrorCode`,
 * so bindings that only see the client (the Angular refs) type its errors.
 */
export const createClient = (options: ClientOptions) =>
  createClientRuntime<typeof resourceMap, Attributes, WriteAttributes, ActionTypes, ErrorCode, Links>(
    resourceMap,
    {
      atomic,
      ...options,
    },
  )
